// كود سيء وصعب القراءة (Deeply Nested Code):
function processPayment(user, cart) {
  if (user) {
    if (user.isLoggedIn) {
      if (cart.items.length > 0) {
        if (user.balance >= cart.total) {
          return "تم الدفع بنجاح";
        } else {
          return "الرصيد غير كافٍ";
        }
      } else {
        return "السلة فارغة";
      }
    } else {
      return "يرجى تسجيل الدخول";
    }
  } else {
    return "المستخدم غير موجود";
  }
}

// كود نظيف، مسطح وسهل الصيانة (Clean Guard Clauses):
function processPayment(user, cart) {
  if (!user) return "المستخدم غير موجود";
  if (!user.isLoggedIn) return "يرجى تسجيل الدخول";
  if (cart.items.length === 0) return "السلة فارغة";
  if (user.balance < cart.total) return "الرصيد غير كافٍ";

  // لو وصلنا هنا، يبقى كل الشروط ممتازة والمسار سالك:
  user.balance -= cart.total;
  return "تم الدفع بنجاح";
}

