function createBankAccount(initialBalance) {
  let balance = initialBalance; // متغير سري خاص (Private)

  return {
    deposit(amount) {
      if (amount > 0) {
        balance += amount;
        return `تم إيداع ${amount}، الرصيد الحالي: ${balance}`;
      }
      return "مبلغ غير صالح";
    },
    withdraw(amount) {
      if (amount <= balance) {
        balance -= amount;
        return `تم سحب ${amount}، الرصيد المتبقي: ${balance}`;
      }
      return "رصيد غير كافٍ";
    },
    getBalance() {
      return balance;
    }
  };
}

