  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b
};

function calculate(type, a, b) {
  const selectedAction = actions[type];
  if (!selectedAction) {
    throw new Error(`العملية [${type}] غير مدعومة`);
  }
  return selectedAction(a, b);
}

