async function manageFiles() {
  try {
    const dataDir = path.join(process.cwd(), "data");

    // 1. إنشاء مجلد بأمان (recursive بيضمن عدم الخطأ لو المجلد موجود مسبقًا):
    await fs.mkdir(dataDir, { recursive: true });

    // 2. كتابة ملف نصي:
    const filePath = path.join(dataDir, "log.txt");
    await fs.writeFile(filePath, "بدأ تشغيل الخادم بنجاح\n", "utf-8");

    // 3. إضافة سطر جديد للملف:
