// قبل إعادة الهيكلة (Deeply Nested Spaghetti):
function registerUser(user) {
  if (user) {
    if (user.email) {
      if (user.age >= 18) {
        return saveUserToDatabase(user);
      } else {
        throw new Error("يجب أن يكون السن 18 فما فوق");
      }
    } else {
      throw new Error("البريد الإلكتروني مطلوب");
    }
