function registerUser(user) {
  if (!user) throw new Error("بيانات المستخدم مطلوبة");
  if (!user.email) throw new Error("البريد الإلكتروني مطلوب");
  if (user.age < 18) throw new Error("يجب أن يكون السن 18 فما فوق");

