const uiState = {
  status: "idle", // "idle" | "loading" | "success" | "error"
  data: null,
  errorMessage: null
};

function renderFeed(state) {
  const container = document.querySelector("#feed-container");

  // 1. حالة التحميل (Loading State):
  if (state.status === "loading") {
    container.innerHTML = `<div class="spinner">جاري تحميل المنشورات...</div>`;
    return;
  }

  // 2. حالة الخطأ (Error State):
  if (state.status === "error") {
    container.innerHTML = `<div class="error-alert">${state.errorMessage}</div>`;
    return;
  }

  // 3. حالة النجاح (Success State):
  if (state.status === "success") {
    container.innerHTML = state.data
      .map(post => `<article class="post-card"><h3>${post.title}</h3></article>`)
      .join("");
  }
}

function debounce(func, delay = 300) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}

// الاستخدام مع خانة البحث:
