import http from "node:http";

const PORT = 4000;

const server = http.createServer(async (req, res) => {
  const { method, url } = req;

  // 1. مسار فحص صحة السيرفر (Health Check):
  if (url === "/api/health" && method === "GET") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ status: "OK", timestamp: new Date().toISOString() }));
    return;
  }

  // 2. مسار غير موجود (404 Not Found):
  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "المسار المطلوب غير موجود" }));
});

server.listen(PORT, () => {
  console.log(`السيرفر يعمل الآن على الرابط: http://localhost:${PORT}`);
});

// نموذج عقلي بسيط للـ Middleware:
function authMiddleware(req, res, next) {
  const token = req.headers["authorization"];
  if (!token) {
    res.writeHead(401, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "غير مصرح، يرجى إرسال التوكن" }));
    return;
  }
  // لو التوكن سليم، نمرر للخطوة التالية:
  next();
}

// 1. طبقة الخدمة (Service - Pure Business Logic):
export class UserService {
  static async getUserProfile(userId) {
    if (!userId) throw new Error("معرف المستخدم مطلوب");
    // محاكاة استعلام قاعدة البيانات:
    return { id: userId, name: "كريم", role: "Developer" };
  }
}

// 2. طبقة التحكم (Controller - HTTP Translation):
export async function getUserHandler(req, res) {
  try {
    const userId = 101;
    const profile = await UserService.getUserProfile(userId);

    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(profile));
  } catch (err) {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: err.message }));
  }
}

