import fs from "node:fs";
import { pipeline } from "node:stream/promises";
import zlib from "node:zlib"; // موديول ضغط الملفات المدمج

async function compressHugeFile(sourcePath, targetPath) {
  try {
    // ضغط وتمرير ملف ضخم بأمان تام عبر pipeline:
    await pipeline(
      fs.createReadStream(sourcePath),  // 1. تدفق قراءة من المصدر
      zlib.createGzip(),                // 2. تدفق ضغط البيانات في الهواء
      fs.createWriteStream(targetPath)  // 3. تدفق كتابة للملف المضغوط
    );
    console.log("تم ضغط الملف بنجاح وبدون استهلاك للرامات!");
  } catch (err) {
    console.error("فشل الضغط:", err.message);
  }
}

import { EventEmitter } from "node:events";

class OrderProcessor extends EventEmitter {
  processOrder(orderId, amount) {
    console.log(`جاري معالجة الطلب رقم: ${orderId}...`);
    // إطلاق حدث اكتمال الطلب مع تمرير البيانات للمستمعين:
    this.emit("order_completed", { orderId, amount, date: new Date() });
  }
}

const processor = new OrderProcessor();

// تسجيل مستمعين للحدث بشكل مستقل تمامًا:
processor.on("order_completed", (data) => {
  console.log(`[إشعار البريد]: تم إرسال فاتورة للطلب ${data.orderId}`);
});

processor.on("order_completed", (data) => {
  console.log(`[إشعار المحاسبة]: تم تسجيل إيراد بقيمة ${data.amount} ج.م`);
});

// تنفيذ المعالجة:
processor.processOrder(9912, 1500);

import crypto from "node:crypto";

// 1. توليد معرف فريد عالميًا (UUID v4):
const uniqueId = crypto.randomUUID();
console.log("معرف عشوائي فريد:", uniqueId);

// 2. تشفير وحساب بصمة نصية (SHA-256 Hash):
const hash = crypto
  .createHash("sha256")
  .update("كلمة_السر_السرية")
  .digest("hex");

console.log("بصمة الهاش المشفرة:", hash);

